pub(super) fn verify_freeze(
    config: &OriginalCellQ24MaterialReceiptConfigV1,
    ledger: &mut LedgerWriter,
    material: &OriginalCellQ24DatasetV1,
    at: u64,
) -> Result<(), Error> {
    // Logical reauthentication after the preceding physical CURRENT/journal
    // reads keeps the original Evaluator credential window current as well.
    // This derives the same receipt; it appends/reserves/signs nothing.
    let receipt = ledger
        .freeze_dataset(config.freeze_plan.clone(), &config.freeze_evidence, at)
        .map_err(CellQ24DatasetErrorV1::from)?;
    if &receipt != material.receipt() {
        return Err(invalid("original freeze changed during receipt readback"));
    }
    let _ = ledger
        .read_dataset_records(&receipt, at)
        .map_err(CellQ24DatasetErrorV1::from)?;
    Ok(())
}

pub fn freeze_dataset(
    &self,
    plan: DatasetFreezePlanV2,
    evidence: &SignedLearningEvidenceV1,
    now: u64,
) -> Result<DatasetSnapshotReceiptV3, ProductionLedgerError> {
    let snapshot = self.backend.snapshot()?;
    let payload = dataset_freeze_signing_payload_v2(&snapshot, &plan)?;
    let verified = self.trust.verifier().verify(
        LearningEvidenceRoleV1::Evaluator,
        evidence,
        &payload,
        now,
    )?;
    require_role(&verified, LearningEvidenceRoleV1::Evaluator)?;
    freeze_dataset_from_ledger(&snapshot, plan, verified.principal().clone(), now)
}

pub fn dataset_freeze_signing_payload_v2(
    snapshot: &LedgerSnapshot,
    plan: &DatasetFreezePlanV2,
) -> Result<Vec<u8>, ProductionLedgerError> {
    let derived = derive_dataset(snapshot, plan)?;
    let mut bytes = b"hepta.learning-ledger.dataset-freeze-plan.v2".to_vec();
    push_id(&mut bytes, &plan.snapshot_id);
    bytes.extend_from_slice(plan.objective_digest.as_array());
    bytes.extend_from_slice(plan.inclusion_policy_digest.as_array());
    bytes.extend_from_slice(snapshot.head_digest.as_array());
    bytes.extend_from_slice(&derived.eligible_frontier.to_be_bytes());
    bytes.extend_from_slice(&derived.outcome_watermark.to_be_bytes());
    bytes.extend_from_slice(derived.correction_cut_digest.as_array());
    bytes.extend_from_slice(derived.revocation_cut_digest.as_array());
    bytes.extend_from_slice(&(derived.source_record_digests.len() as u64).to_be_bytes());
    for digest in derived.source_record_digests {
        bytes.extend_from_slice(digest.as_array());
    }
    Ok(bytes)
}

pub fn freeze_dataset_from_ledger(
    snapshot: &LedgerSnapshot,
    plan: DatasetFreezePlanV2,
    producer: AuthenticatedPrincipalV1,
    now: u64,
) -> Result<DatasetSnapshotReceiptV3, ProductionLedgerError> {
    producer
        .validate(now)
        .map_err(ProductionLedgerError::Causal)?;
    let derived = derive_dataset(snapshot, &plan)?;
    let request = DatasetFreezeRequestV1 {
        snapshot_id: plan.snapshot_id,
        producer,
        ledger_head_digest: snapshot.head_digest,
        objective_digest: plan.objective_digest,
        eligible_frontier: derived.eligible_frontier,
        outcome_watermark: derived.outcome_watermark,
        correction_cut_digest: derived.correction_cut_digest,
        revocation_cut_digest: derived.revocation_cut_digest,
        inclusion_policy_digest: plan.inclusion_policy_digest,
        source_record_digests: derived.source_record_digests,
        pending_outcomes: derived.pending_outcomes,
        censored_outcomes: derived.censored_outcomes,
    };
    freeze_dataset_receipt_v3(request, now).map_err(Into::into)

pub fn activate_learning_trust(
    root: &LearningTrustRootV1,
    signed: SignedLearningTrustDistributionV1,
    previous: Option<&ActivatedLearningTrustV1>,
    now: u64,
) -> Result<ActivatedLearningTrustV1, LearningTrustDistributionError> {
    let root_digest = validate_root(root, now)?;
    if signed.root_id != root.root_id {
        return Err(LearningTrustDistributionError::RootMismatch);
    }
    if signed.issued_at > now
        || signed.issued_at > signed.expires_at
        || signed.issued_at > signed.distribution.effective_at
        || now > signed.expires_at
        || signed.issued_at < root.valid_from
        || signed.expires_at > root.expires_at
    {
        return Err(LearningTrustDistributionError::DistributionWindow);
    }

    let distribution = &signed.distribution;
    if distribution.generation == 0
        || distribution.effective_at > now
        || distribution.trust.scope_digest != root.scope_digest
    {
        return Err(LearningTrustDistributionError::InvalidGeneration);
    }

    let verifier = LearningEvidenceVerifierV1::new(distribution.trust.clone())?;
    let payload = distribution_signing_bytes(
        &signed.root_id,
        distribution,
        signed.issued_at,
        signed.expires_at,
    )?;
    VerifyingKey::from_bytes(&root.verifying_key)
        .map_err(|_| LearningTrustDistributionError::InvalidRoot)?
        .verify_strict(&payload, &Signature::from_bytes(&signed.signature))
        .map_err(|_| LearningTrustDistributionError::InvalidSignature)?;

    if let Some(previous) = previous {
        let expected = previous
            .generation
            .checked_add(1)
            .ok_or(LearningTrustDistributionError::InvalidGeneration)?;
        if previous.root_digest != root_digest || previous.root_id != root.root_id {
            return Err(LearningTrustDistributionError::RootRotationRequiresCeremony);
        }
        if distribution.generation != expected
            || distribution.effective_at < previous.effective_at
            || verifier.authority_epoch() < previous.verifier.authority_epoch()
        {
            return Err(LearningTrustDistributionError::NonMonotonicRotation);
        }
    }

    let distribution_digest = digest_distribution(
        root_digest,
        &distribution.distribution_id,
        distribution.generation,
        distribution.effective_at,
        signed.issued_at,
        signed.expires_at,
        &verifier,
    );
    Ok(ActivatedLearningTrustV1 {
        root_id: root.root_id.clone(),
        root_digest,
        distribution_id: distribution.distribution_id.clone(),
        generation: distribution.generation,
        effective_at: distribution.effective_at,
        distribution_digest,
        verifier,
    })
}

